(35473, 'deDE', 'Bonuszielbelohnung: Das Ausmerzen von Stratholme', '', '', '', '', '', '', '', '', 19865),
(35474, 'deDE', 'Culling of Stratholme Reward Quest', '', '', '', '', '', '', '', '', 19865),
