(35626, 'deDE', 'Konstrukteurslehrling Andren', '', '', '', '', '', '', '', '', 19865),
(35627, 'deDE', 'Schatz: Korb mit Arakkoawaren', '', '', '', '', '', '', '', '', 19865),
(35628, 'deDE', 'Rangari Chel', '', '', '', '', '', '', '', '', 19865),
