(35941, 'deDE', 'Trollfüße', '', '', '', '', '', '', '', '', 19865),
(35942, 'deDE', 'Pandarenfell', '', '', '', '', '', '', '', '', 19865),
(35943, 'deDE', 'Nagrand - Vignette Boss 026 - Duretha', '', '', '', '', '', '', '', '', 19865),
(35944, 'deDE', 'Stärkebeweis: Gorenzahn', 'Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.', 'Dieser Zahn ist ein Beweis für Eure Stärke im Töten von Goren, und Euer Gladiatorfreund kann es bezeugen!$b$bBringt den Zahn zu Jonaa und nehmt Eure Anerkennung entgegen!', '', '', '', '', '', '', 19865),
(35945, 'deDE', 'Greblin Flinkzünd', 'Helft Greblin Flinkzünd nach unten.', 'Ich hänge hier schon ewig rum!$b$bIch bin hier rumgeflogen, hab das Gebiet für Nixxie vermessen und dann... BÄMM! Einer dieser blöden Oger hat einen Stein nach mir geworfen. Hat mich direkt getroffen!$b$bMein Gleiter ist abgestürzt und ich sitz hier fest... und, Mann, ist das unbequem.$b$bHelft mir bitte runter, ja? Ich sorge auch dafür, dass es sich für Euch lohnt.', '', '', '', '', '', 'Sprecht mit Greblin Flinkzünd bei der Zerschlagenen Anhöhe in Nagrand.', 19865),
(35946, 'deDE', 'Picker der Majestätische', 'Nehmt den Blutschwur von Klingenmeisterin Na''Shra an.', 'Ihr habt mir einen großen Dienst erwiesen. Diese Klinge gehört Euch jetzt ebenso wie mir.$b$bIch biete Euch einen Blutschwur an: Ich werde Euch dienen und Euren Truppen mein Wissen über Klingen und den Bergbau zur Verfügung stellen.$b$BSeid Ihr damit einverstanden?', '', '', 'Klingenmeisterin Na''Shra', '', '', '', 19865),
(35947, 'deDE', 'Die Macht des Giftes', 'Befragt Orcs der Zerschmetterten Hand in der Ausschlachterei und findet den Namen und den Aufenthaltsort von "G.G." heraus.', 'G.G.? Wir brauchen einen Namen und eine Ortsangabe. Keine verdammten Initialen.$B$B<Velonara holt eine kleine Phiole hervor.>$B$BDas ist mein letztes Fläschchen Foltergift. Wir benutzen es, um Gefangenen Informationen zu entlocken. Es ist... wirksam.$B$BBestreicht Eure Waffe damit und geht zum Lager der Zerschmetterten Hand ein Stück weiter. Verwickelt sie einfach in einen Kampf und verlangt Antworten... den Rest wird das Gift übernehmen. Ich habe genug von diesen Orcs.', '', '', '', '', '', 'Sprecht mit der dunklen Waldläuferin Velonara in der Schattenwacht.', 19865),
(35948, 'deDE', 'Stärkebeweis: Gorenzahn', 'Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.', 'Dieser Zahn ist ein Beweis für Eure Fähigkeit im Töten von Goren, und Euer Gladiatorfreund kann es bezeugen!$b$bBringt den Zahn zu Schinder und nehmt Eure Anerkennung entgegen!', '', '', '', '', '', '', 19865),
