(36465, 'deDE', 'Verfolgungsquest: Schatzkarte', '', '', '', '', '', '', '', '', 19865),
(36466, 'deDE', 'Verfolgungsquest: Schatzkarte', '', '', '', '', '', '', '', '', 19865),
