(36901, 'deDE', 'Tracking Quest: Vivianne', '', '', '', '', '', '', '', '', 19865),
(36902, 'deDE', 'Tracking Quest: Aeda Brightdawn', '', '', '', '', '', '', '', '', 19865),
(36903, 'deDE', 'Ogre Waygate', '', '', '', '', '', '', '', '', 19865),
(36904, 'deDE', 'Ogre Waygate', '', '', '', '', '', '', '', '', 19865),
